update releases r
set tags = coalesce(r.tags, ARRAY[]::text[])
  || case when d.prj_tag is not null and not exists (
       select 1 from unnest(coalesce(r.tags, ARRAY[]::text[])) x where x like 'PRJ\_%' escape '\'
     ) then ARRAY[d.prj_tag] else ARRAY[]::text[] end
  || case when d.pub_tag is not null and not exists (
       select 1 from unnest(coalesce(r.tags, ARRAY[]::text[])) x where x like 'PUB\_%' escape '\'
     ) then ARRAY[d.pub_tag] else ARRAY[]::text[] end
  || (select coalesce(array_agg(f), ARRAY[]::text[]) from unnest(d.free_tags) f where f <> ALL(coalesce(r.tags, ARRAY[]::text[])))
from import_data d
where r.upc = d.upc
and (
  (d.prj_tag is not null and not exists (select 1 from unnest(coalesce(r.tags, ARRAY[]::text[])) x where x like 'PRJ\_%' escape '\'))
  or (d.pub_tag is not null and not exists (select 1 from unnest(coalesce(r.tags, ARRAY[]::text[])) x where x like 'PUB\_%' escape '\'))
  or exists (select 1 from unnest(d.free_tags) f where f <> ALL(coalesce(r.tags, ARRAY[]::text[])))
);

